"""Session config for ComPIL splits generated by data/ComPIL/build_compil.py.

Builds the same module-level names as the PromptCCZSL readers (cgqa_read_datasets.py etc.),
with sessions named "<dataset>-s0" .. "<dataset>-s{K-1}" (one per ComPIL task).
Each fS cell (step k, task j <= k) is an extra session "<dataset>-s{k}-fs{j}": identical to
session k except that its test images are task j's seen test images plus session k's unseen ones.
"""
import ast
import json
import os


def _load_keys(path):
    with open(path, encoding="utf-8") as f:
        return list(json.load(f).keys())


def _load_pair_keys(path):
    return [ast.literal_eval(k) for k in _load_keys(path)]


def _count_lines(path):
    with open(path, encoding="utf-8") as f:
        return sum(1 for line in f if line.strip())


def build_config(dataset, images_root, generated_dir):
    with open(os.path.join(generated_dir, "summary.json"), encoding="utf-8") as f:
        summary = json.load(f)
    sessions = [f"{dataset}-s{t['task']}" for t in summary["tasks"]]

    cfg = {
        "DATASET_PATHS": {dataset: images_root},
        "selected_session_g_pair2_idx": sessions[-1],
        "t7_files": {}, "teacher_t7_files": {}, "train_val_test_txtfiles": {},
        "ALL_ATTR_OBJ_PAIRS": {}, "TRAIN_PAIRS": {},
        "ALL_ATTR_OBJ": {}, "g_objattrpair2idx_path": {},
    }
    for k, s in enumerate(sessions):
        task_dir = os.path.join(generated_dir, f"task{k}")
        idx = os.path.join(task_dir, "idx")
        attrs = _load_keys(os.path.join(idx, "attr2idx.json"))
        objs = _load_keys(os.path.join(idx, "obj2idx.json"))
        pairs = _load_pair_keys(os.path.join(idx, "pair2idx.json"))

        # Each task has its own .t7 (current-task train images; see data/ComPIL/build_compil.py).
        # The teacher of session k is task k-1, as in the PromptCCZSL readers.
        cfg["t7_files"][s] = os.path.join(generated_dir, summary["tasks"][k]["t7"])
        cfg["teacher_t7_files"][s] = os.path.join(generated_dir, summary["tasks"][max(k - 1, 0)]["t7"])
        cfg["train_val_test_txtfiles"][s] = task_dir
        cfg["ALL_ATTR_OBJ_PAIRS"][s] = (len(attrs), len(objs))
        cfg["TRAIN_PAIRS"][s] = _count_lines(os.path.join(task_dir, "train_pairs.txt"))
        cfg["ALL_ATTR_OBJ"][s] = {"all_attrs": attrs, "all_objs": objs, "all_pairs": pairs}
        cfg["g_objattrpair2idx_path"][s] = {
            "g_obj2idx": objs,
            "g_attr2idx": attrs,
            "g_pair2idx": {p: i for i, p in enumerate(pairs)},
        }
        for j, fs_t7 in summary["tasks"][k].get("fs_t7", {}).items():
            cell = f"{s}-fs{j}"
            for key in cfg:
                if isinstance(cfg[key], dict) and s in cfg[key]:
                    cfg[key][cell] = cfg[key][s]
            cfg["t7_files"][cell] = cfg["teacher_t7_files"][cell] = os.path.join(generated_dir, fs_t7)
    return cfg
